test('renderInvoiceText shows line discount when present', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });
  const text = renderInvoiceText(inv.value);
  const lines = text.split('\n');
  assert(lines[3].includes('Discount:'));
});

test('renderInvoiceText does not show discount when line has no discount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(inv.value);
  assert(!text.includes('Discount:'));
});

test('renderInvoiceText shows voucher before total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const withVoucher = applyVoucher(inv.value, { code: 'SAVE100', amount: 5000 });
  const text = renderInvoiceText(withVoucher.value);
  const lines = text.split('\n');
  const voucherLine = lines.findIndex((l) => l.startsWith('Voucher:'));
  const totalLine = lines.findIndex((l) => l.startsWith('Total:'));
  assert(voucherLine >= 0);
  assert(totalLine > voucherLine);
});

test('renderInvoiceText shows due date when present', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);
  const text = renderInvoiceText(issued.value);
  assert(text.includes('Due: 2026-10-15'));
});

test('renderInvoiceText does not show due date when missing', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(inv.value);
  assert(!text.includes('Due:'));
});

test('renderInvoiceText shows paid amount when payments exist', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);
  const partial = recordPayment(issued.value, { amount: 5000, date: '2026-10-02' });
  const text = renderInvoiceText(partial.value);
  assert(text.includes('Paid: €50.00'));
});

test('renderInvoiceText aggregates multiple payments', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);
  const after1st = recordPayment(issued.value, { amount: 5000, date: '2026-10-02' });
  const after2nd = recordPayment(after1st.value, { amount: 3000, date: '2026-10-03' });
  const text = renderInvoiceText(after2nd.value);
  assert(text.includes('Paid: €80.00'));
});

test('renderInvoiceText does not show paid when no payments', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(inv.value);
  assert(!text.includes('Paid:'));
});

test('renderInvoiceText with all enhancements together', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 15, discountPercent: 5 }],
    terms: 'NET14',
  });
  const withVoucher = applyVoucher(inv.value, { code: 'SAVE50', amount: 5000 });
  const issued = issueInvoice(withVoucher.value, []);
  const partial = recordPayment(issued.value, { amount: 50000, date: '2026-10-02' });
  const text = renderInvoiceText(partial.value);
  const lines = text.split('\n');
  assert(lines.some((l) => l.includes('Discount:')));
  assert(lines.some((l) => l.startsWith('Voucher:')));
  assert(lines.some((l) => l.startsWith('Paid:')));
  assert(lines.some((l) => l.startsWith('Due:')));
  assert(lines.some((l) => l.startsWith('Total:')));
});

